import sys
from collections import deque

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:]))

    degree = [0] * (n + 1)
    for i in range(n):
        degree[i + 1] = a[i]

    queue = deque()
    for i in range(1, n + 1):
        if degree[i] == 0:
            queue.append(i)

    order = []
    while queue:
        if len(queue) < 3:
            break
        x = queue.popleft()
        y = queue.popleft()
        z = queue.popleft()
        order.extend([x, y, z])
        degree[x] -= 2
        degree[y] -= 2
        degree[z] -= 2

        for w in range(1, n + 1):
            if degree[w] > 0 and w not in {x, y, z}:
                degree[w] -= 1
                if degree[w] == 0:
                    queue.append(w)

    if len(order) != n:
        print("Impossible")
        return

    remaining = [i for i in range(1, n + 1) if i not in order]
    for i in range(n):
        if degree[order[i]] != 0:
            print("Impossible")
            return

    print("Possible")
    print(" ".join(map(str, order + remaining)))

if __name__ == "__main__":
    main()
